var feedback,chosenFiles;class Feedback{submit(){const n=$("#gameForm");this.validateContent(n)&&(n.find("#submitBtn").prop("disabled",!0),$.ajax({method:"POST",url:"/feedback/AddFeedback",dataType:"json",data:n.serialize()}).done(function(t){t.success?(n.find("#failedMsg").hide(),parent.postMessage("------------hello!-----cocos---------","*"),feedback.showSuccessModal(""),n.find("#submitBtn").prop("disabled",!1)):(n.find("#failedMsg").show(),n.find("#failedMsgContent").html(t.message),n.find("#submitBtn").prop("disabled",!1))}))}validateContent(n){var t=$("#descText").val();return t===""?(n.find("#failedMsg").show(),n.find("#failedMsgContent").html("(The description can't be empty)"),!1):(n.find("#failedMsg").hide(),!0)}showSuccessModal(){const n=$("#editModal");name||(name="");n.modal("show")}openSelectFile(){$("#myfile").trigger("click")}}feedback=new Feedback;$("#descText").keyup(function(){feedback.validateContent($("#gameForm"))});chosenFiles=[];$("#myfile").on("change",function(n){var t=n.target.files[0];chosenFiles.push(t);console.log(t.name);console.log(chosenFiles)});